export function allExploreDecks(): ExploreDeck[] {
  return EXPLORE_SECTIONS.flatMap(s => s.decks);
}

export function exploreDeckById(id: string): ExploreDeck | undefined {
  return allExploreDecks().find(d => d.id === id);
}

export function starIdsOf(deck: ExploreDeck): string[] {
  return deck.cards.map(c => `xp:${deck.id}:${c.de}`);
}
